/// Called first by every hook: points FabricLoader's config folder at the mod's data folder, then runs
/// the mod's initializer, once.
pub fn ensure_init(game: &mut crate::game::Game<'_>) {
    if INIT.is_completed() {
        return;
    }
    INIT.call_once(|| {
        J_DATA_DIR.set(Some(game.native_data_dir(crate::game::port_xaerominimap::ID)));
        on_init(game);
    });
}

/// A translated text's English pattern with its arguments: `%s`, `%d`, `%1$s` and `%%`, as Minecraft fills them.
fn j_lang(pattern: &str, args: &[String]) -> String {
    let mut out = String::new();
    let mut next = 0;
    let mut chars = pattern.chars().peekable();
    while let Some(c) = chars.next() {
        if c != '%' {
            out.push(c);
            continue;
        }
        let mut digits = String::new();
        while let Some(d) = chars.peek().copied().filter(|d| d.is_ascii_digit()) {
            digits.push(d);
            chars.next();
        }
        let index = if chars.peek() == Some(&'$') {
            chars.next();
            digits.parse::<usize>().ok().map(|n| n.saturating_sub(1))
        } else {
            None
        };
        match chars.next() {
            Some('%') => out.push('%'),
            Some('s') | Some('d') => {
                let i = index.unwrap_or_else(|| {
                    next += 1;
                    next - 1
                });
                out.push_str(args.get(i).map_or("", |s| s.as_str()));
            }
            Some(o) => {
                out.push('%');
                out.push(o);
            }
            None => out.push('%'),
        }
    }
    out
}

